/// Autogenerated property names do not describe business state. Infer only a
/// complete default/hover[/active] axis with identical non-root state content.
fn promote_unnamed_state_axis(
    definitions: &mut [Definition],
    records: &mut [Record],
) -> Option<String> {
    if definitions
        .iter()
        .any(|d| d.name.eq_ignore_ascii_case("effect"))
    {
        return None;
    }
    let candidates = definitions
        .iter()
        .enumerate()
        .filter(|(_, d)| {
            let name = d
                .source
                .split('#')
                .next()
                .unwrap_or_default()
                .chars()
                .filter(|c| !c.is_whitespace())
                .collect::<String>()
                .to_ascii_lowercase();
            let number = name
                .strip_prefix("property")
                .or_else(|| name.strip_prefix("\u{c18d}\u{c131}"));
            !d.boolean
                && number.is_some_and(|n| !n.is_empty() && n.chars().all(|c| c.is_ascii_digit()))
                && d.default == "default"
                && d.options.iter().any(|v| v == "default")
                && d.options.iter().any(|v| v == "hover")
                && d.options
                    .iter()
                    .all(|v| matches!(v.as_str(), "default" | "hover" | "active"))
        })
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let [index] = candidates.as_slice() else {
        return None;
    };
    let definition = &definitions[*index];
    let mut groups = BTreeMap::<BTreeMap<String, String>, Vec<&Record>>::new();
    for record in records.iter() {
        let fixed = record
            .values
            .iter()
            .filter(|(name, _)| *name != &definition.source)
            .map(|(name, value)| (name.clone(), value.clone()))
            .collect();
        groups.entry(fixed).or_default().push(record);
    }
    if groups.is_empty()
        || !groups.values().all(|group| {
            let Some(baseline) = group
                .iter()
                .find(|r| r.values.get(&definition.source) == Some(&definition.default))
            else {
                return false;
            };
            definition.options.iter().all(|option| {
                group
                    .iter()
                    .any(|r| r.values.get(&definition.source) == Some(option))
            }) && group
                .iter()
                .all(|r| root_only_state_change(&baseline.tree, &r.tree, true))
        })
    {
        return None;
    }
    let source = definitions[*index].source.clone();
    definitions[*index].name = "effect".into();
    definitions[*index].source = "effect".into();
    for record in records {
        if let Some(value) = record.values.remove(&source) {
            record.values.insert("effect".into(), value);
        }
    }
    Some(source)
}

fn root_only_state_change(base: &Tree, other: &Tree, root: bool) -> bool {
    base.component == other.component
        && !base.is_component
        && !other.is_component
        && base.component != "Image"
        && base.content == other.content
        && base.visible_when == other.visible_when
        && base.children.len() == other.children.len()
        && (root || (base.props == other.props && base.node_name == other.node_name))
        && base
            .children
            .iter()
            .zip(&other.children)
            .all(|(left, right)| root_only_state_change(left, right, false))
}

fn state_axis_diagnostics(
    set: &RawNode,
    definitions: &[Definition],
    inferred: Option<&str>,
) -> Vec<Diagnostic> {
    let mut diagnostics = Vec::new();
    if let Some(axis) = inferred {
        diagnostics.push(Diagnostic {
            code:"DEVUP_CODEGEN_UNNAMED_STATE_AXIS".into(),
            message:"An autogenerated pure default/hover/active axis with identical captured descendants was projected as root CSS states. Runtime semantics and event wiring are still consumer responsibilities.".into(),
            node_id:Some(set.id.clone()),severity:Some(DiagnosticSeverity::Info),
            details:Some(serde_json::json!({"sourceAxis":axis,"mapping":{"default":"&","hover":"_hover","active":"_active"},"runtimeVerified":false,"output":"componentTsx"})),
            ..Diagnostic::default()
        });
    }
    for axis in definitions.iter().filter(|d| {
        d.name.eq_ignore_ascii_case("effect")
            && d.options.iter().any(|v| effect_selector(v).is_none())
    }) {
        diagnostics.push(Diagnostic {
            code:"DEVUP_CODEGEN_MIXED_STATE_AXIS".into(),
            message:"An interaction axis mixes CSS states with runtime variants. It remains an explicit prop; map states to the captured viewport/base owner instead of coercing every value to a pseudo-state.".into(),
            node_id:Some(set.id.clone()),severity:Some(DiagnosticSeverity::Warning),
            details:Some(serde_json::json!({"sourceAxis":axis.source,"options":axis.options,"preservedAsProp":true,"runtimeVerified":false,"output":"componentTsx"})),
            ..Diagnostic::default()
        });
    }
    diagnostics
}
